def init_mapping(self):
    import heapq
    from collections import defaultdict, deque

    N = self.num_qubits
    self.mapping_dict = [-1] * N
    self.reverse_mapping_dict = [-1] * N

    # 1. Gather logical qubits and pairwise weights.
    qig = getattr(self, "qubit_interaction_graph", None)
    pair_weight = defaultdict(float)
    logical_qubits = set()

    if qig is not None and len(qig) > 0:
        for u, nbrs in qig.items():
            logical_qubits.add(u)
            for v, w in nbrs.items():
                logical_qubits.add(v)
                if u < v:
                    pair_weight[(u, v)] += float(w)
                elif v < u:
                    pair_weight[(v, u)] += float(w)
    else:
        for gate_id, qubits in self.access.items():
            if len(qubits) == 2:
                a, b = qubits[0], qubits[1]
                logical_qubits.add(a)
                logical_qubits.add(b)
                if a == b:
                    continue
                key = (a, b) if a < b else (b, a)
                pair_weight[key] += 1.0

    # Include 1-qubit-only logicals too.
    for gate_id, qubits in self.access.items():
        for q in qubits:
            logical_qubits.add(q)

    # Weight lookup helper.
    def w_between(a, b):
        if qig is not None:
            return float(qig[a].get(b, 0)) if hasattr(qig[a], "get") else float(qig[a][b])
        if a == b:
            return 0.0
        key = (a, b) if a < b else (b, a)
        return pair_weight.get(key, 0.0)

    free_phys = set(range(N))
    placed = {}            # logical -> physical
    placed_logicals = []   # order of placement

    # 2. Seed on highest-frequency logical pair + most central physical edge.
    if pair_weight:
        (lA, lB), _ = max(pair_weight.items(), key=lambda kv: kv[1])

        centrality = getattr(self, "physical_centrality", {})
        def cent(p):
            try:
                return float(centrality.get(p, 0.0))
            except AttributeError:
                return float(centrality[p]) if p in centrality else 0.0

        best_edge = None
        best_score = -float("inf")
        seen_edge = set()
        for (pa, pb) in self.backend_connections:
            if pa == pb:
                continue
            key = (pa, pb) if pa < pb else (pb, pa)
            if key in seen_edge:
                continue
            seen_edge.add(key)
            s = cent(pa) + cent(pb)
            if s > best_score:
                best_score = s
                best_edge = (pa, pb)

        if best_edge is None:
            # Degenerate: no edges. Place on two most central qubits.
            sorted_phys = sorted(range(N), key=lambda p: -cent(p))
            if len(sorted_phys) >= 2:
                best_edge = (sorted_phys[0], sorted_phys[1])
            else:
                best_edge = (0, 0)

        pA, pB = best_edge
        # Order: anchor strongest logical (by activity) on most central physical.
        activity = getattr(self, "logical_activity", None)
        def act(q):
            if activity is None:
                return 0.0
            try:
                return float(activity.get(q, 0))
            except AttributeError:
                return float(activity[q]) if q in activity else 0.0

        if act(lA) < act(lB) or (act(lA) == act(lB) and cent(pA) < cent(pB)):
            lA, lB = lB, lA
        if cent(pA) < cent(pB):
            pA, pB = pB, pA

        placed[lA] = pA
        placed[lB] = pB
        free_phys.discard(pA)
        free_phys.discard(pB)
        placed_logicals.extend([lA, lB])

    # 3. Affinity: unplaced logical -> total weight to placed logicals.
    affinity = defaultdict(float)
    strongest_partner = {}  # unplaced_logical -> (best_weight, placed_logical)

    def add_affinity_from(newly_placed):
        for L in logical_qubits:
            if L in placed:
                continue
            w = w_between(L, newly_placed)
            if w > 0:
                affinity[L] += w
                cur = strongest_partner.get(L)
                if cur is None or w > cur[0] or (w == cur[0] and newly_placed < cur[1]):
                    strongest_partner[L] = (w, newly_placed)

    for pl in placed_logicals:
        add_affinity_from(pl)

    # 4. Priority-driven BFS expansion.
    def closest_free_neighbor(src_phys):
        # BFS over coupling graph; return first free physical encountered.
        if src_phys in free_phys:
            return src_phys
        visited = {src_phys}
        dq = deque([src_phys])
        while dq:
            cur = dq.popleft()
            for nb in self.backend.get(cur, ()):
                if nb in visited:
                    continue
                visited.add(nb)
                if nb in free_phys:
                    return nb
                dq.append(nb)
        # Fallback: closest free by distance_matrix.
        best = None
        best_d = float("inf")
        for p in free_phys:
            d = self.distance_matrix[src_phys][p]
            if d < best_d:
                best_d = d
                best = p
        return best

    while affinity and free_phys:
        # Pick unplaced logical with max affinity (ties: lower id).
        L = max(affinity.keys(), key=lambda q: (affinity[q], -q))
        if affinity[L] <= 0:
            break
        partner = strongest_partner.get(L)
        if partner is None:
            del affinity[L]
            continue
        anchor_phys = placed[partner[1]]
        chosen = closest_free_neighbor(anchor_phys)
        if chosen is None:
            break

        placed[L] = chosen
        free_phys.discard(chosen)
        del affinity[L]
        strongest_partner.pop(L, None)
        add_affinity_from(L)

    # 5. Place remaining logicals that appeared in access but have no interactions.
    centrality_local = getattr(self, "physical_centrality", {})
    def cent2(p):
        try:
            return float(centrality_local.get(p, 0.0))
        except AttributeError:
            return float(centrality_local[p]) if p in centrality_local else 0.0

    remaining_logicals = sorted(
        [q for q in logical_qubits if q not in placed],
        key=lambda q: -(getattr(self, "logical_activity", {}).get(q, 0)
                        if hasattr(getattr(self, "logical_activity", {}), "get") else 0)
    )
    for L in remaining_logicals:
        if not free_phys:
            break
        # Pick most central free physical.
        chosen = max(free_phys, key=lambda p: (cent2(p), -p))
        placed[L] = chosen
        free_phys.discard(chosen)

    # 6. Identity fill for any logical id in [0, N) still unplaced.
    used_phys = set(placed.values())
    free_sorted = sorted(p for p in range(N) if p not in used_phys)
    free_iter = iter(free_sorted)
    for L in range(N):
        if L in placed:
            continue
        try:
            p = next(free_iter)
        except StopIteration:
            break
        placed[L] = p
        used_phys.add(p)

    # Safety: if any conflicts (shouldn't happen), rebuild via identity over remaining.
    final_used = set()
    for L in range(N):
        p = placed.get(L, -1)
        if p == -1 or p in final_used or not (0 <= p < N):
            placed[L] = -1
        else:
            final_used.add(p)
    leftover = [p for p in range(N) if p not in final_used]
    li = iter(leftover)
    for L in range(N):
        if placed.get(L, -1) == -1:
            try:
                placed[L] = next(li)
            except StopIteration:
                placed[L] = L  # last-resort identity

    for L in range(N):
        p = placed[L]
        self.mapping_dict[L] = p
        if 0 <= p < N:
            self.reverse_mapping_dict[p] = L

    assert len(set(self.mapping_dict)) == len(self.mapping_dict)

def init_mapping(self):
    import math
    N = self.num_qubits

    mapping = [-1] * N
    reverse = [-1] * N
    used_phys = set()
    placed_log = set()

    # 1) Build weighted logical adjacency from access (fallback to QIG).
    edge_weight = {}
    adj = {}
    active_logicals = set()
    for gate_id, qubits in self.access.items():
        if len(qubits) == 2:
            a, b = qubits[0], qubits[1]
            active_logicals.add(a)
            active_logicals.add(b)
            if a == b:
                continue
            key = (a, b) if a < b else (b, a)
            edge_weight[key] = edge_weight.get(key, 0) + 1
        elif len(qubits) == 1:
            active_logicals.add(qubits[0])

    qig = getattr(self, "qubit_interaction_graph", None)
    if not edge_weight and qig is not None:
        for u, nbrs in qig.items():
            for v, w in nbrs.items():
                if u == v or w <= 0:
                    continue
                key = (u, v) if u < v else (v, u)
                if key not in edge_weight:
                    edge_weight[key] = w
                active_logicals.add(u)
                active_logicals.add(v)

    for (a, b), w in edge_weight.items():
        adj.setdefault(a, {})[b] = w
        adj.setdefault(b, {})[a] = w

    centrality = getattr(self, "physical_centrality", {}) or {}
    def cscore(p):
        return centrality.get(p, 0.0)

    dist = self.distance_matrix
    logical_activity = getattr(self, "logical_activity", {})
    def lact(q):
        if hasattr(logical_activity, "get"):
            return logical_activity.get(q, 0)
        return 0

    def assign(log_q, phys_q):
        mapping[log_q] = phys_q
        reverse[phys_q] = log_q
        used_phys.add(phys_q)
        placed_log.add(log_q)

    # 2) Seed: heaviest logical edge -> most-central adjacent physical pair.
    sorted_edges = sorted(edge_weight.items(), key=lambda kv: -kv[1])
    if sorted_edges:
        (u_seed, v_seed), _ = sorted_edges[0]
        best_pair = None
        best_key = None
        for p in range(N):
            for q in range(p + 1, N):
                if dist[p][q] != 1:
                    continue
                k = (-(cscore(p) + cscore(q)), p, q)
                if best_key is None or k < best_key:
                    best_key = k
                    best_pair = (p, q)
        if best_pair is None:
            best_kd = None
            for p in range(N):
                for q in range(p + 1, N):
                    d = dist[p][q]
                    if d <= 0:
                        continue
                    k = (d, -(cscore(p) + cscore(q)), p, q)
                    if best_kd is None or k < best_kd:
                        best_kd = k
                        best_pair = (p, q)
        if best_pair is not None and u_seed < N and v_seed < N:
            p, q = best_pair
            if cscore(p) >= cscore(q):
                hi_p, lo_p = p, q
            else:
                hi_p, lo_p = q, p
            if lact(u_seed) >= lact(v_seed):
                assign(u_seed, hi_p); assign(v_seed, lo_p)
            else:
                assign(v_seed, hi_p); assign(u_seed, lo_p)

    # 3) Helper: pick the unused physical minimizing weighted distance
    #    sum to log_q's already-placed neighbors (ties: higher centrality).
    def best_phys_for(log_q):
        nbrs = adj.get(log_q, {})
        placed_nbr_items = [(n, w) for n, w in nbrs.items() if n in placed_log]
        best_p = None
        best_key = None
        for p in range(N):
            if p in used_phys:
                continue
            cost = 0
            for n, w in placed_nbr_items:
                cost += w * dist[p][mapping[n]]
            key = (cost, -cscore(p), p)
            if best_key is None or key < best_key:
                best_key = key
                best_p = p
        return best_p

    # 4) GREEDY AFFINITY EXPANSION (the hypothesis):
    #    Repeatedly pick the unplaced logical with maximum interaction-weight
    #    sum to the placed frontier and place it at minimum weighted distance
    #    to its placed neighbors. This directly minimizes pairwise affinity
    #    cost rather than matching global rank statistics.
    def expand_frontier():
        while True:
            best_log = None
            best_aff = -1
            best_tb = None
            for L in active_logicals:
                if L in placed_log or L >= N:
                    continue
                aff = 0
                for n, w in adj.get(L, {}).items():
                    if n in placed_log:
                        aff += w
                if aff <= 0:
                    continue
                tb = (-lact(L), L)
                if aff > best_aff or (aff == best_aff and tb < best_tb):
                    best_aff = aff
                    best_tb = tb
                    best_log = L
            if best_log is None:
                return
            p_target = best_phys_for(best_log)
            if p_target is None:
                return
            assign(best_log, p_target)

    expand_frontier()

    # 5) Reseed any disconnected logical components, then keep expanding.
    remaining = sorted(
        (L for L in active_logicals if L not in placed_log and L < N),
        key=lambda L: -lact(L),
    )
    for L in remaining:
        if L in placed_log:
            continue
        unused_sorted = sorted(
            (p for p in range(N) if p not in used_phys),
            key=lambda p: -cscore(p),
        )
        if not unused_sorted:
            break
        assign(L, unused_sorted[0])
        expand_frontier()

    # 6) Identity-preferred backfill for inactive logical slots.
    for L in range(N):
        if mapping[L] != -1:
            continue
        if L not in used_phys:
            assign(L, L)
    for L in range(N):
        if mapping[L] != -1:
            continue
        for P in range(N):
            if P not in used_phys:
                assign(L, P)
                break

    self.mapping_dict = mapping
    self.reverse_mapping_dict = reverse
    assert len(set(self.mapping_dict)) == len(self.mapping_dict)

def init_mapping(self):
    from collections import defaultdict, deque

    N = self.num_qubits
    self.mapping_dict = [-1] * N
    self.reverse_mapping_dict = [-1] * N

    # --- 1. Gather logical qubits + pairwise interaction weights ---------------
    qig = getattr(self, "qubit_interaction_graph", None)
    tig = getattr(self, "temporal_interaction_graph", None)
    pair_weight = defaultdict(float)
    logical_qubits = set()

