        for u, nbrs in qig.items():
            logical_qubits.add(u)
            for v, w in nbrs.items():
                logical_qubits.add(v)
                if u < v:
                    pair_weight[(u, v)] += float(w)
                elif v < u:
                    pair_weight[(v, u)] += float(w)
    else:
        for gate_id, qubits in self.access.items():
            if len(qubits) == 2:
                a, b = qubits[0], qubits[1]
                logical_qubits.add(a)
                logical_qubits.add(b)
                if a != b:
                    key = (a, b) if a < b else (b, a)
                    pair_weight[key] += 1.0

    for gate_id, qubits in self.access.items():
        for q in qubits:
            logical_qubits.add(q)

    def w_between(a, b):
        if a == b:
            return 0.0
        if qig is not None:
            row = qig[a] if a in qig else None
            if row is None:
                key = (a, b) if a < b else (b, a)
                return pair_weight.get(key, 0.0)
            return float(row.get(b, 0)) if hasattr(row, "get") else float(row[b])
        key = (a, b) if a < b else (b, a)
        return pair_weight.get(key, 0.0)

    # --- 2. Activity (hypothesis h4): gate frequency + earliest-use tiebreak ---
    activity_attr = getattr(self, "logical_activity", None)

    def activity(q):
        if activity_attr is not None:
            try:
                v = activity_attr.get(q, 0)
            except AttributeError:
                v = activity_attr[q] if q in activity_attr else 0
            if v:
                return float(v)
        total = 0.0
        for (a, b), w in pair_weight.items():
            if a == q or b == q:
                total += w
        return total

    def temporal_weight(q):
        if tig is None:
            return 0.0
        row = tig.get(q) if hasattr(tig, "get") else (tig[q] if q in tig else None)
        if not row:
            return 0.0
        total = 0.0
        for _, w in row.items():
            total += float(w)
        return total

    activity_score = {q: activity(q) for q in logical_qubits}
    temporal_score = {q: temporal_weight(q) for q in logical_qubits}

    # Strict activity-priority ordering: highest gate frequency first.
    logical_order = sorted(
        logical_qubits,
        key=lambda q: (-activity_score[q], -temporal_score[q], q),
    )

    # --- 3. Centrality helpers --------------------------------------------------
    centrality = getattr(self, "physical_centrality", {}) or {}

    def cent(p):
        try:
            return float(centrality.get(p, 0.0))
        except AttributeError:
            return float(centrality[p]) if p in centrality else 0.0

    free_phys = set(range(N))
    placed = {}  # logical -> physical

    def closest_free_neighbor(src_phys):
        if src_phys in free_phys:
            return src_phys
        visited = {src_phys}
        dq = deque([src_phys])
        while dq:
            cur = dq.popleft()
            for nb in self.backend.get(cur, ()):
                if nb in visited:
                    continue
                visited.add(nb)
                if nb in free_phys:
                    return nb
                dq.append(nb)
        best = None
        best_d = float("inf")
        for p in free_phys:
            d = self.distance_matrix[src_phys][p]
            if d < best_d:
                best_d = d
                best = p
        return best

    def most_central_free():
        chosen = None
        best_c = -float("inf")
        for p in free_phys:
            c = cent(p)
            if c > best_c or (c == best_c and (chosen is None or p < chosen)):
                best_c = c
                chosen = p
        return chosen

    # --- 4. Activity-driven placement (HYPOTHESIS h4) --------------------------
    # Incrementally track each unplaced logical's strongest already-placed partner.
    strongest_partner = {}  # unplaced_L -> (weight, placed_L)

    def refresh_partners_after_placing(newly_placed):
        for L in logical_qubits:
            if L in placed:
                continue
            w = w_between(L, newly_placed)
            if w <= 0:
                continue
            cur = strongest_partner.get(L)
            if cur is None or w > cur[0] or (w == cur[0] and newly_placed < cur[1]):
                strongest_partner[L] = (w, newly_placed)

    for L in logical_order:
        if not free_phys:
            break
        if L in placed:
            continue

        partner_entry = strongest_partner.get(L)
        if partner_entry is None or partner_entry[0] <= 0:
            # No placed bond: top-activity logical seizes the most central seat.
            chosen = most_central_free()
        else:
            anchor_phys = placed[partner_entry[1]]
            chosen = closest_free_neighbor(anchor_phys)
            if chosen is None:
                chosen = most_central_free()

        if chosen is None:
            break
        placed[L] = chosen
        free_phys.discard(chosen)
        strongest_partner.pop(L, None)
        refresh_partners_after_placing(L)

    # --- 5. Identity fill for logical ids in [0, N) without interactions -------
    used_phys = set(placed.values())
    free_sorted = sorted(p for p in range(N) if p not in used_phys)
    free_iter = iter(free_sorted)
    for L in range(N):
        if L in placed:
            continue
        try:
            p = next(free_iter)
        except StopIteration:
            break
        placed[L] = p
        used_phys.add(p)

    # --- 6. Safety: resolve any conflicts / out-of-range placements ------------
    final_used = set()
    for L in range(N):
        p = placed.get(L, -1)
        if p == -1 or p in final_used or not (0 <= p < N):
            placed[L] = -1
        else:
            final_used.add(p)
    leftover = [p for p in range(N) if p not in final_used]
    li = iter(leftover)
    for L in range(N):
        if placed.get(L, -1) == -1:
            try:
                placed[L] = next(li)
            except StopIteration:
                placed[L] = L

    for L in range(N):
        p = placed[L]
        self.mapping_dict[L] = p
        if 0 <= p < N:
            self.reverse_mapping_dict[p] = L

    assert len(set(self.mapping_dict)) == len(self.mapping_dict)

