        return float(activity[q]) if q in activity else 0.0

    free_phys = set(range(N))
    placed = {}
    placed_logicals = []
    D = self.distance_matrix

    # 2. Seed: strongest-interacting logical pair onto the most central coupling edge.
    if pair_weight:
        (lA, lB), _ = max(
            pair_weight.items(),
            key=lambda kv: (kv[1], -(kv[0][0] + kv[0][1])),
