    for L in logical_qubits:
        if L in placed:
            continue
        s = 0.0
        for P in placed_logicals:
            w = w_between(L, P)
            if w > 0:
                s += w
        if s > 0:
            affinity[L] = s

    def best_phys_for(L):
        # Minimise sum_{P placed} w(L,P) * D[candidate][phys(P)].
        # Tie-break by higher physical centrality, then lower physical id.
        contributors = [(w_between(L, P), placed[P])
                        for P in placed_logicals]
        contributors = [(w, ph) for (w, ph) in contributors if w > 0]
        if not contributors:
            # No interactions yet — pick most central free physical.
            return max(free_phys, key=lambda p: (cent(p), -p)) if free_phys else None

        best_p = None
        best_cost = float("inf")
        best_cent = -float("inf")
        for p in free_phys:
            cost = 0.0
            prune = False
            row_p = D[p]
            for (w, ph) in contributors:
                cost += w * row_p[ph]
                if cost > best_cost:
                    prune = True
                    break
            if prune:
                continue
            if cost < best_cost:
                best_cost = cost
                best_p = p
                best_cent = cent(p)
            elif cost == best_cost:
                cp = cent(p)
                if cp > best_cent or (cp == best_cent and (best_p is None or p < best_p)):
                    best_p = p
                    best_cent = cp
        return best_p

    while affinity and free_phys:
        # Pick unplaced logical with maximum affinity (ties: higher activity, then lower id).
        L = max(affinity.keys(), key=lambda q: (affinity[q], act(q), -q))
        del affinity[L]
        p_chosen = best_phys_for(L)
        if p_chosen is None:
            break
        placed[L] = p_chosen
        free_phys.discard(p_chosen)
        placed_logicals.append(L)
        # Refresh affinity for any unplaced logical that interacts with L.
        for M in logical_qubits:
            if M in placed:
                continue
            w = w_between(M, L)
            if w > 0:
                affinity[M] = affinity.get(M, 0.0) + w

    # 4. Place remaining logicals (no interactions placed) on most central free physicals.
    remaining = sorted(
        [q for q in logical_qubits if q not in placed],
        key=lambda q: (-act(q), q),
    )
    for L in remaining:
        if not free_phys:
            break
        chosen = max(free_phys, key=lambda p: (cent(p), -p))
        placed[L] = chosen
        free_phys.discard(chosen)

    # 5. Identity fill for any logical id in [0, N) still unplaced.
    used_phys = set(placed.values())
    free_sorted = sorted(p for p in range(N) if p not in used_phys)
    fi = iter(free_sorted)
    for L in range(N):
        if L in placed:
            continue
        try:
            placed[L] = next(fi)
        except StopIteration:
            break

    # 6. Safety: rebuild any conflicts via identity over leftover physicals.
    final_used = set()
    for L in range(N):
        p = placed.get(L, -1)
        if p == -1 or p in final_used or not (0 <= p < N):
            placed[L] = -1
        else:
            final_used.add(p)
    leftover = [p for p in range(N) if p not in final_used]
    li = iter(leftover)
    for L in range(N):
        if placed.get(L, -1) == -1:
            try:
                placed[L] = next(li)
            except StopIteration:
                placed[L] = L

    for L in range(N):
        p = placed[L]
        self.mapping_dict[L] = p
        if 0 <= p < N:
            self.reverse_mapping_dict[p] = L

    assert len(set(self.mapping_dict)) == len(self.mapping_dict)

def init_mapping(self):
    import random

    N = self.num_qubits

    interactions = []
    for _gid, qubits in self.access.items():
        if len(qubits) == 2:
            a, b = qubits[0], qubits[1]
            if a != b:
                interactions.append((a, b))

    dist = self.distance_matrix

    def qig_w(a, b):
        inner = self.qubit_interaction_graph.get(a) if hasattr(self.qubit_interaction_graph, "get") else None
        if inner is None:
            try:
                return self.qubit_interaction_graph[a][b]
            except Exception:
                return 0
        return inner.get(b, 0)

    def activity(q):
        if hasattr(self.logical_activity, "get"):
            return self.logical_activity.get(q, 0)
        try:
            return self.logical_activity[q]
        except Exception:
            return 0

    def centrality(p):
        if hasattr(self.physical_centrality, "get"):
            return self.physical_centrality.get(p, 0.0)
        try:
            return self.physical_centrality[p]
        except Exception:
            return 0.0

    def swap_lower_bound(mapping):
        total = 0
        for a, b in interactions:
            d = dist[mapping[a]][mapping[b]]
            if d > 1:
                total += d - 1
        return total

    def is_valid_perm(m):
        if m is None or len(m) != N:
            return False
        if any((p is None or p < 0 or p >= N) for p in m):
            return False
        return len(set(m)) == N

    def cand_identity():
        return list(range(N))

    def cand_activity_centrality(reverse=False):
        logicals = sorted(range(N), key=lambda q: (-activity(q), q))
        physicals = sorted(range(N), key=lambda p: (-centrality(p), p))
        if reverse:
            physicals = list(reversed(physicals))
        m = [0] * N
        for lg, ph in zip(logicals, physicals):
            m[lg] = ph
        return m

    def cand_greedy_qig():
        m = [-1] * N
        used_phys = [False] * N
        placed = [False] * N

        logicals_by_act = sorted(range(N), key=lambda q: (-activity(q), q))
        physicals_by_cent = sorted(range(N), key=lambda p: (-centrality(p), p))

        seed_log = logicals_by_act[0]
        seed_phys = physicals_by_cent[0]
        m[seed_log] = seed_phys
        used_phys[seed_phys] = True
        placed[seed_log] = True

        for _ in range(N - 1):
            best_log, best_score = -1, -1
            for q in range(N):
                if placed[q]:
                    continue
                s = 0
                for qp in range(N):
                    if placed[qp]:
                        s += qig_w(q, qp)
                if s > best_score or (s == best_score and best_log == -1):
                    best_score = s
                    best_log = q
            if best_log < 0:
                break
            if best_score <= 0:
                for q in logicals_by_act:
                    if not placed[q]:
                        best_log = q
                        break

            best_phys, best_cost = -1, float("inf")
            for p in range(N):
                if used_phys[p]:
                    continue
                cost = 0.0
                for qp in range(N):
                    if placed[qp]:
                        w = qig_w(best_log, qp)
                        if w:
                            cost += w * dist[p][m[qp]]
                cost -= 1e-9 * centrality(p)
                if cost < best_cost:
                    best_cost = cost
                    best_phys = p
            if best_phys < 0:
                for p in physicals_by_cent:
                    if not used_phys[p]:
                        best_phys = p
                        break
            m[best_log] = best_phys
            used_phys[best_phys] = True
            placed[best_log] = True

        for q in range(N):
            if not placed[q]:
                for p in physicals_by_cent:
                    if not used_phys[p]:
                        m[q] = p
                        used_phys[p] = True
                        placed[q] = True
                        break
        return m

    def cand_random(seed):
        rng = random.Random(seed)
        perm = list(range(N))
        rng.shuffle(perm)
        return perm

    candidates = []
    for builder in (cand_identity,
                    lambda: cand_activity_centrality(False),
                    lambda: cand_activity_centrality(True),
                    cand_greedy_qig):
        try:
            c = builder()
            if is_valid_perm(c):
                candidates.append(c)
        except Exception:
            pass

    for seed in (1, 7, 19, 41, 97, 211, 523, 1031):
        try:
            c = cand_random(seed)
            if is_valid_perm(c):
                candidates.append(c)
        except Exception:
            pass

    if not candidates:
        candidates.append(list(range(N)))

    best = min(candidates, key=swap_lower_bound)

    self.mapping_dict = list(best)
    self.reverse_mapping_dict = [0] * N
    for lg in range(N):
        self.reverse_mapping_dict[self.mapping_dict[lg]] = lg

    assert len(set(self.mapping_dict)) == len(self.mapping_dict)

def init_mapping(self):
    import math
    import random
    from collections import defaultdict

    N = self.num_qubits
    D = self.distance_matrix

    # 1) Collect 2-qubit interactions from self.access
    edge_w = defaultdict(int)
    active = set()
    for _gid, qubits in self.access.items():
        if len(qubits) == 2:
            a, b = qubits[0], qubits[1]
            if a == b:
                continue
            if a > b:
                a, b = b, a
            edge_w[(a, b)] += 1
            active.add(a)
            active.add(b)

    adj = defaultdict(list)
    edges = []
    for (a, b), w in edge_w.items():
        adj[a].append((b, w))
        adj[b].append((a, w))
        edges.append((a, b, w))

    log_act = defaultdict(int)
    for q, nbrs in adj.items():
        for (_nb, w) in nbrs:
            log_act[q] += w

    # 2) HYPOTHESIS: anchor the most-active logical at the centrality-maximal physical,
    #    then grow outward into the densest connectivity region.
    pi = [None] * N
    used_phys = set()

    centrality = getattr(self, "physical_centrality", None)
    if centrality:
        hub_phys = max(range(N), key=lambda p: centrality.get(p, 0.0))
    else:
        hub_phys = min(range(N), key=lambda p: sum(D[p][q] for q in range(N)))

    if active:
        hub_log = max(active, key=lambda q: log_act.get(q, 0))
    else:
        hub_log = 0

    pi[hub_log] = hub_phys
    used_phys.add(hub_phys)
    placed = {hub_log}

    # Radial expansion: pick unplaced logical with max weighted attachment to placed set,
    # place on unused physical minimizing weighted distance to placed neighbors.
    while True:
        best_q = None
        best_w = -1
        for q in active:
            if q in placed:
                continue
            w_sum = 0
            for (nb, w) in adj[q]:
                if nb in placed:
                    w_sum += w
            if w_sum > best_w or (
                w_sum == best_w and best_q is not None and log_act[q] > log_act[best_q]
            ):
                best_w = w_sum
                best_q = q
        if best_q is None:
            remaining_active = [q for q in active if q not in placed]
            if not remaining_active:
                break
            best_q = max(remaining_active, key=lambda q: log_act.get(q, 0))
            best_w = 0

        best_p = None
        best_cost = float("inf")
        placed_nbrs = [(nb, w) for (nb, w) in adj[best_q] if nb in placed]
        if placed_nbrs:
            # Prefer physicals near the placed neighbors (i.e. close to the hub region)
            for p in range(N):
                if p in used_phys:
                    continue
                cost = 0.0
                for (nb, w) in placed_nbrs:
                    cost += w * D[p][pi[nb]]
                if cost < best_cost:
                    best_cost = cost
                    best_p = p
        else:
            # Disconnected component: still keep it inside the dense region near the hub
            for p in range(N):
                if p in used_phys:
                    continue
                cost = D[p][hub_phys]
                if centrality:
                    cost -= 1e-6 * centrality.get(p, 0.0)
                if cost < best_cost:
                    best_cost = cost
                    best_p = p
        if best_p is None:
            for p in range(N):
                if p not in used_phys:
                    best_p = p
                    break

        pi[best_q] = best_p
        used_phys.add(best_p)
        placed.add(best_q)

    # Idle logicals onto the most central remaining physicals (hub-priority back-fill)
    if centrality:
        free_phys = sorted(
            (p for p in range(N) if p not in used_phys),
            key=lambda p: -centrality.get(p, 0.0),
        )
    else:
        free_phys = [p for p in range(N) if p not in used_phys]
    fi = 0
    for L in range(N):
        if pi[L] is None:
            pi[L] = free_phys[fi]
            used_phys.add(free_phys[fi])
            fi += 1

    # 3) Energy + simulated-annealing refinement (from better parent)
    def total_energy(perm):
        e = 0.0
        for (a, b, w) in edges:
            e += w * D[perm[a]][perm[b]]
        return e

    cur_E = total_energy(pi)
    best_pi = list(pi)
    best_E = cur_E

    if edges and len(active) >= 2:
        rng = random.Random(0xC0FFEE)
        active_list = list(active)
        iters = max(2000, 50 * N + 20 * len(edges))
        iters = min(iters, 50000)
        T0 = max(1.0, 0.5 * (cur_E / max(1, len(edges))) + 1.0)
        T_end = 1e-3
        cooling = (T_end / T0) ** (1.0 / max(1, iters - 1))
        T = T0

        for _ in range(iters):
            i = active_list[rng.randrange(len(active_list))]
            j = rng.randrange(N)
            if j == i:
                j = (j + 1) % N
            before = 0.0
            for (nb, w) in adj[i]:
                if nb == j:
                    before += w * D[pi[i]][pi[j]]
                else:
                    before += w * D[pi[i]][pi[nb]]
            for (nb, w) in adj[j]:
                if nb == i:
                    continue
                before += w * D[pi[j]][pi[nb]]
            pi[i], pi[j] = pi[j], pi[i]
            after = 0.0
            for (nb, w) in adj[i]:
                if nb == j:
                    after += w * D[pi[i]][pi[j]]
                else:
                    after += w * D[pi[i]][pi[nb]]
            for (nb, w) in adj[j]:
                if nb == i:
                    continue
                after += w * D[pi[j]][pi[nb]]
            dE = after - before
            if dE <= 0 or rng.random() < math.exp(-dE / max(T, 1e-12)):
                cur_E += dE
                if cur_E < best_E:
                    best_E = cur_E
                    best_pi = list(pi)
            else:
                pi[i], pi[j] = pi[j], pi[i]
            T *= cooling

        pi = best_pi

    self.mapping_dict = list(pi)
    self.reverse_mapping_dict = [0] * N
    for L in range(N):
        self.reverse_mapping_dict[self.mapping_dict[L]] = L

    assert len(set(self.mapping_dict)) == len(self.mapping_dict)

def init_mapping(self):
    from collections import defaultdict, deque

    N = self.num_qubits
    self.mapping_dict = [-1] * N
    self.reverse_mapping_dict = [-1] * N

    # ---------- 1. Gather logical qubits and pairwise weights ----------
    qig = getattr(self, "qubit_interaction_graph", None)
    pair_weight = defaultdict(float)
    logical_qubits = set()

    if qig is not None and len(qig) > 0:
        for u, nbrs in qig.items():
            logical_qubits.add(u)
            for v, w in nbrs.items():
                logical_qubits.add(v)
                if u < v:
                    pair_weight[(u, v)] += float(w)
                elif v < u:
                    pair_weight[(v, u)] += float(w)
    else:
        for gate_id, qubits in self.access.items():
            if len(qubits) == 2:
                a, b = qubits[0], qubits[1]
                logical_qubits.add(a); logical_qubits.add(b)
                if a == b:
                    continue
                key = (a, b) if a < b else (b, a)
                pair_weight[key] += 1.0

    for gate_id, qubits in self.access.items():
        for q in qubits:
            logical_qubits.add(q)

    def w_between(a, b):
        if a == b:
            return 0.0
        key = (a, b) if a < b else (b, a)
        return pair_weight.get(key, 0.0)

    # Symmetric neighbor map for fast objective evaluation in local search
    logical_neighbors = defaultdict(dict)
    for (a, b), w in pair_weight.items():
        logical_neighbors[a][b] = w
        logical_neighbors[b][a] = w

    centrality = getattr(self, "physical_centrality", {})
    def cent(p):
        try:
            return float(centrality.get(p, 0.0))
        except AttributeError:
            return float(centrality[p]) if p in centrality else 0.0

    activity = getattr(self, "logical_activity", None)
    def act(q):
        if activity is None:
            return 0.0
        try:
            return float(activity.get(q, 0))
        except AttributeError:
            return float(activity[q]) if q in activity else 0.0

    # ---------- 2. Warm-start: seed on heaviest pair + most-central edge ----------
    free_phys = set(range(N))
    placed = {}
    placed_logicals = []

    if pair_weight:
        (lA, lB), _ = max(pair_weight.items(), key=lambda kv: kv[1])

        best_edge, best_score = None, -float("inf")
        seen_edge = set()
        for (pa, pb) in self.backend_connections:
            if pa == pb:
                continue
            key = (pa, pb) if pa < pb else (pb, pa)
            if key in seen_edge:
                continue
            seen_edge.add(key)
            s = cent(pa) + cent(pb)
            if s > best_score:
                best_score = s
                best_edge = (pa, pb)

        if best_edge is None:
            sorted_phys = sorted(range(N), key=lambda p: -cent(p))
            best_edge = (sorted_phys[0], sorted_phys[1]) if len(sorted_phys) >= 2 else (0, 0)

        pA, pB = best_edge
        if act(lA) < act(lB) or (act(lA) == act(lB) and cent(pA) < cent(pB)):
            lA, lB = lB, lA
        if cent(pA) < cent(pB):
            pA, pB = pB, pA

        placed[lA] = pA
        placed[lB] = pB
        free_phys.discard(pA); free_phys.discard(pB)
        placed_logicals.extend([lA, lB])

    # ---------- 3. Affinity-driven BFS growth ----------
    affinity = defaultdict(float)
    strongest_partner = {}

    def add_affinity_from(newly_placed):
        for L in logical_qubits:
            if L in placed:
                continue
            w = w_between(L, newly_placed)
            if w > 0:
                affinity[L] += w
                cur = strongest_partner.get(L)
                if cur is None or w > cur[0] or (w == cur[0] and newly_placed < cur[1]):
                    strongest_partner[L] = (w, newly_placed)

    for pl in placed_logicals:
        add_affinity_from(pl)

    def closest_free_neighbor(src_phys):
        if src_phys in free_phys:
            return src_phys
        visited = {src_phys}
        dq = deque([src_phys])
        while dq:
            cur = dq.popleft()
            for nb in self.backend.get(cur, ()):
                if nb in visited:
                    continue
                visited.add(nb)
                if nb in free_phys:
                    return nb
                dq.append(nb)
        best, best_d = None, float("inf")
        for p in free_phys:
            d = self.distance_matrix[src_phys][p]
            if d < best_d:
                best_d, best = d, p
        return best

    while affinity and free_phys:
        L = max(affinity.keys(), key=lambda q: (affinity[q], -q))
        if affinity[L] <= 0:
            break
        partner = strongest_partner.get(L)
        if partner is None:
            del affinity[L]; continue
        anchor_phys = placed[partner[1]]
        chosen = closest_free_neighbor(anchor_phys)
        if chosen is None:
            break
        placed[L] = chosen
        free_phys.discard(chosen)
        del affinity[L]
        strongest_partner.pop(L, None)
        add_affinity_from(L)

    # ---------- 4. Isolated logicals & identity fill ----------
    remaining_logicals = sorted(
        [q for q in logical_qubits if q not in placed],
        key=lambda q: -act(q)
    )
    for L in remaining_logicals:
        if not free_phys:
            break
        chosen = max(free_phys, key=lambda p: (cent(p), -p))
        placed[L] = chosen
        free_phys.discard(chosen)

    used_phys = set(placed.values())
    free_sorted = sorted(p for p in range(N) if p not in used_phys)
    free_iter = iter(free_sorted)
    for L in range(N):
        if L in placed:
            continue
        try:
            p = next(free_iter)
        except StopIteration:
            break
        placed[L] = p
        used_phys.add(p)

    final_used = set()
    for L in range(N):
        p = placed.get(L, -1)
        if p == -1 or p in final_used or not (0 <= p < N):
            placed[L] = -1
        else:
            final_used.add(p)
    leftover = [p for p in range(N) if p not in final_used]
    li = iter(leftover)
    for L in range(N):
        if placed.get(L, -1) == -1:
            try:
                placed[L] = next(li)
            except StopIteration:
                placed[L] = L

    # ---------- 5. HYPOTHESIS: pairwise-swap local search on warm start ----------
    # Directly minimize  SUM_{(u,v)} w(u,v) * DM[map(u)][map(v)]  on the *true*
    # hardware graph (no coarsening), via a bounded-neighborhood best-improvement
    # 2-swap, iterated until a pass yields no gain.
    DM = self.distance_matrix
    rev = [-1] * N
    for L in range(N):
        p = placed[L]
        if 0 <= p < N:
            rev[p] = L

    active_logicals = [L for L in range(N) if logical_neighbors.get(L)]
    weight_total = {L: sum(logical_neighbors[L].values()) for L in active_logicals}

    def delta_swap(L1, L2):
        p1 = placed[L1]; p2 = placed[L2]
        if p1 == p2 or not (0 <= p1 < N) or not (0 <= p2 < N):
            return 0.0
        d = 0.0
        for v, w in logical_neighbors.get(L1, {}).items():
            if v == L2:
                continue
            pv = placed[v]
            if not (0 <= pv < N):
                continue
            d += w * (DM[p2][pv] - DM[p1][pv])
        for v, w in logical_neighbors.get(L2, {}).items():
            if v == L1:
                continue
            pv = placed[v]
            if not (0 <= pv < N):
                continue
            d += w * (DM[p1][pv] - DM[p2][pv])
        return d

    max_passes = 8
    for _ in range(max_passes):
        improved = False
        order = sorted(active_logicals, key=lambda q: -weight_total.get(q, 0.0))
        for L1 in order:
            p1 = placed[L1]
            if not (0 <= p1 < N):
                continue
            # Candidate partners: logicals on physicals adjacent to p1, plus
            # logicals on physicals adjacent to L1's logical-neighbors' physicals.
            cand = set()
            for nb in self.backend.get(p1, ()):
                if 0 <= nb < N and rev[nb] != -1:
                    cand.add(rev[nb])
            for v in logical_neighbors.get(L1, {}):
                pv = placed.get(v, -1)
                if not (0 <= pv < N):
                    continue
                for nb in self.backend.get(pv, ()):
                    if 0 <= nb < N and rev[nb] != -1:
                        cand.add(rev[nb])
            cand.discard(L1)

            best_partner, best_delta = None, -1e-12
            for L2 in cand:
                d = delta_swap(L1, L2)
                if d < best_delta:
                    best_delta = d
                    best_partner = L2
            if best_partner is not None:
                p2 = placed[best_partner]
                placed[L1], placed[best_partner] = p2, p1
                rev[p1] = best_partner
                rev[p2] = L1
                improved = True
        if not improved:
            break

    # ---------- 6. Commit ----------
    for L in range(N):
        p = placed[L]
        self.mapping_dict[L] = p
        if 0 <= p < N:
            self.reverse_mapping_dict[p] = L

    assert len(set(self.mapping_dict)) == len(self.mapping_dict)

def init_mapping(self):
    import math
    import random
    from collections import defaultdict, deque

    N = self.num_qubits
    D = self.distance_matrix
    backend = self.backend
    centrality = self.physical_centrality
    activity = self.logical_activity

    # ---------- 1) Gather 2q interactions (weighted) ----------
    edge_w = defaultdict(int)
    active = set()
    for _gid, qubits in self.access.items():
        if len(qubits) == 2:
            a, b = qubits[0], qubits[1]
            if a == b or not (0 <= a < N) or not (0 <= b < N):
                continue
            if a > b:
                a, b = b, a
            edge_w[(a, b)] += 1
            active.add(a)
            active.add(b)

    edges = [(a, b, w) for (a, b), w in edge_w.items()]

    adj = defaultdict(list)
    for (a, b, w) in edges:
        adj[a].append((b, w))
        adj[b].append((a, w))

    def _act(q):
        try:
            return activity.get(q, 0) if hasattr(activity, "get") else activity[q]
        except Exception:
            return 0

    def _cen(p):
        try:
            return centrality.get(p, 0.0) if hasattr(centrality, "get") else 0.0
        except Exception:
            return 0.0

    all_phys = list(range(N))
    phys_by_cen = sorted(all_phys, key=lambda p: (-_cen(p), p))

    # ---------- 2) Candidate constructors ----------
    def _validate(perm):
        if perm is None or len(perm) != N:
            return None
        seen = set()
        out = [None] * N
        for L in range(N):
            p = perm[L]
            if p is None or not (0 <= p < N) or p in seen:
                continue
            out[L] = p
            seen.add(p)
        free = [p for p in range(N) if p not in seen]
        fi = 0
        for L in range(N):
            if out[L] is None:
                out[L] = free[fi]
                fi += 1
        return out

    def cand_identity():
        return list(range(N))

    def cand_structure_aware():
        try:
            from src.mapping.initial_mapping import generate_structure_aware_initial_mapping
            md, _ = generate_structure_aware_initial_mapping(
                self.access, backend, D, N
            )
            return _validate(md)
        except Exception:
            return None

    def cand_activity_centrality():
        # highest-activity logical -> highest-centrality physical
        logicals = sorted(range(N), key=lambda q: (-_act(q), q))
        perm = [0] * N
        used = set()
        pi = 0
        for L in logicals:
            while pi < N and phys_by_cen[pi] in used:
                pi += 1
            P = phys_by_cen[pi] if pi < N else 0
            perm[L] = P
            used.add(P)
            pi += 1
        return _validate(perm)

    def cand_weighted_bfs_path(rng=None):
        # logical path by greedy heaviest-edge walk; physical path by greedy
        # most-central walk on hardware. Pair them index-by-index.
        in_circ = set(active) if active else set(range(N))
        if not in_circ:
            return list(range(N))
        if rng is None:
            seed_log = max(in_circ, key=lambda q: (_act(q), -q))
        else:
            # weighted random seed proportional to activity
            cand = list(in_circ)
            weights = [max(1, _act(q)) for q in cand]
            seed_log = rng.choices(cand, weights=weights, k=1)[0]
        logical_path = [seed_log]
        visited = {seed_log}
        cur = seed_log
        while len(logical_path) < len(in_circ):
            nbrs = [(nb, w) for (nb, w) in adj.get(cur, []) if nb not in visited and nb in in_circ]
            if nbrs:
                if rng is None:
                    nb = max(nbrs, key=lambda nw: (nw[1], _act(nw[0]), -nw[0]))[0]
                else:
                    weights = [max(1, w) for (_, w) in nbrs]
                    nb = rng.choices([n for (n, _) in nbrs], weights=weights, k=1)[0]
            else:
                remaining = in_circ - visited
                if not remaining:
                    break
                nb = max(remaining, key=lambda q: (_act(q), -q))
            logical_path.append(nb)
            visited.add(nb)
            cur = nb
        for q in range(N):
            if q not in visited:
                logical_path.append(q)
                visited.add(q)

        seed_phys = phys_by_cen[0] if phys_by_cen else 0
        phys_path = [seed_phys]
        vp = {seed_phys}
        cp = seed_phys
        while len(phys_path) < N:
            nbrs = [nb for nb in backend.get(cp, set()) if nb not in vp and 0 <= nb < N]
            if nbrs:
                nb = max(nbrs, key=lambda p: (_cen(p), -p))
            else:
                rem = [p for p in all_phys if p not in vp]
                if not rem:
                    break
                nb = max(rem, key=lambda p: (_cen(p), -p))
            phys_path.append(nb)
            vp.add(nb)
            cp = nb

        perm = [0] * N
        used_phys = set()
        used_log = set()
        for L, P in zip(logical_path, phys_path):
            if L in used_log or P in used_phys:
                continue
            perm[L] = P
            used_log.add(L)
            used_phys.add(P)
        # fill any leftovers
        rem_l = [q for q in range(N) if q not in used_log]
        rem_p = [p for p in range(N) if p not in used_phys]
        rem_p.sort(key=lambda p: (-_cen(p), p))
        rem_l.sort(key=lambda q: (-_act(q), q))
        for L, P in zip(rem_l, rem_p):
            perm[L] = P
        return _validate(perm)

    def cand_bfs_anchor_expansion(rng=None):
        # Place heaviest edge first, then BFS-expand by heaviest pending edge,
        # placing each new logical onto the closest free neighbour of its
        # already-placed neighbour(s).
        if not edges:
            return list(range(N))
        edge_sorted = sorted(edges, key=lambda e: -e[2])
        a0, b0, _ = edge_sorted[0]
        # anchor onto two adjacent central physical qubits
        anchor = None
        for p in phys_by_cen:
            for q in backend.get(p, set()):
                if q != p and 0 <= q < N:
                    anchor = (p, q)
                    break
            if anchor:
                break
        if anchor is None:
            anchor = (0, 1 if N > 1 else 0)
        perm = [None] * N
        used_phys = set()
        perm[a0] = anchor[0]; used_phys.add(anchor[0])
        perm[b0] = anchor[1]; used_phys.add(anchor[1])

        # priority by max neighbour edge-weight to placed set
        placed = {a0, b0}
        # Iteratively pick highest-weight unplaced logical adjacent to placed set
        while True:
            best = None
            best_w = -1
            for q in placed:
                for (nb, w) in adj.get(q, []):
                    if nb in placed:
                        continue
                    if w > best_w:
                        best_w = w
                        best = nb
            if best is None:
                break
            # choose best free physical: minimize Σ w * d(p, perm[neighbour])
            best_p = None
            best_cost = None
            for p in range(N):
                if p in used_phys:
                    continue
                cost = 0.0
                for (nb, w) in adj.get(best, []):
                    if perm[nb] is not None:
                        cost += w * D[p][perm[nb]]
                if best_cost is None or cost < best_cost or (
                    cost == best_cost and _cen(p) > _cen(best_p)
                ):
                    best_cost = cost
                    best_p = p
            perm[best] = best_p
            used_phys.add(best_p)
            placed.add(best)

        # fill idles by activity vs centrality
        rem_l = [q for q in range(N) if perm[q] is None]
        rem_p = [p for p in range(N) if p not in used_phys]
        rem_p.sort(key=lambda p: (-_cen(p), p))
        rem_l.sort(key=lambda q: (-_act(q), q))
        for L, P in zip(rem_l, rem_p):
            perm[L] = P
        return _validate(perm)

    # Build candidate pool
    candidates = []
    for builder in (cand_identity, cand_structure_aware,
                    cand_activity_centrality, cand_weighted_bfs_path,
                    cand_bfs_anchor_expansion):
        try:
            c = builder()
            if c is not None:
                candidates.append(c)
        except Exception:
            pass
    # Add a few randomized variants for diversity
    rng_seed = random.Random(0xBEEF)
    for _ in range(3):
        try:
            c = cand_weighted_bfs_path(rng_seed)
            if c is not None:
                candidates.append(c)
        except Exception:
            pass

    # Deduplicate
    uniq = []
    seen_tuples = set()
    for c in candidates:
        t = tuple(c)
        if t not in seen_tuples:
            seen_tuples.add(t)
            uniq.append(c)
    candidates = uniq if uniq else [list(range(N))]

    # ---------- 3) Rank by SWAP lower bound ----------
    def swap_lower_bound(perm):
        s = 0
        for (a, b, w) in edges:
            d = D[perm[a]][perm[b]]
            if d > 1:
                s += w * (d - 1)
        return s

    best_perm = min(candidates, key=swap_lower_bound)
    best_lb = swap_lower_bound(best_perm)

    # ---------- 4) Short SA polish on the winner ----------
    pi = list(best_perm)

    def total_energy(perm):
        e = 0.0
        for (a, b, w) in edges:
            e += w * D[perm[a]][perm[b]]
        return e

    if edges and len(active) >= 2:
        cur_E = total_energy(pi)
        best_E = cur_E
        best_pi = list(pi)
        rng = random.Random(0xC0FFEE)
        active_list = list(active)
        iters = max(1500, 30 * N + 15 * len(edges))
        iters = min(iters, 30000)
        T0 = max(1.0, 0.5 * (cur_E / max(1, len(edges))) + 1.0)
        T_end = 1e-3
        cooling = (T_end / T0) ** (1.0 / max(1, iters - 1))
        T = T0

        for _ in range(iters):
            i = active_list[rng.randrange(len(active_list))]
            j = rng.randrange(N)
            if j == i:
                j = (j + 1) % N
            before = 0.0
            for (nb, w) in adj[i]:
                if nb == j:
                    before += w * D[pi[i]][pi[j]]
                else:
                    before += w * D[pi[i]][pi[nb]]
            for (nb, w) in adj[j]:
                if nb == i:
                    continue
                before += w * D[pi[j]][pi[nb]]
            pi[i], pi[j] = pi[j], pi[i]
            after = 0.0
            for (nb, w) in adj[i]:
                if nb == j:
                    after += w * D[pi[i]][pi[j]]
                else:
                    after += w * D[pi[i]][pi[nb]]
            for (nb, w) in adj[j]:
                if nb == i:
                    continue
                after += w * D[pi[j]][pi[nb]]
            dE = after - before
            if dE <= 0 or rng.random() < math.exp(-dE / max(T, 1e-12)):
                cur_E += dE
                if cur_E < best_E:
                    best_E = cur_E
                    best_pi = list(pi)
            else:
                pi[i], pi[j] = pi[j], pi[i]
            T *= cooling

        pi = best_pi

    # Final guard: re-rank polished pi against original winner using the
    # SWAP lower bound to make the hypothesis the deciding criterion.
    if swap_lower_bound(pi) > best_lb:
        pi = list(best_perm)

    # ---------- 5) Write outputs ----------
    self.mapping_dict = list(pi)
    self.reverse_mapping_dict = [0] * N
    for L in range(N):
        self.reverse_mapping_dict[self.mapping_dict[L]] = L

    assert len(set(self.mapping_dict)) == len(self.mapping_dict)

def init_mapping(self):
    import math
    import random
    from collections import defaultdict

    N = self.num_qubits
    D = self.distance_matrix
    cent = getattr(self, "physical_centrality", {}) or {}
    act = getattr(self, "logical_activity", {}) or {}

    # 1) Collect 2-qubit interactions from self.access
    edge_w = defaultdict(int)
    active = set()
    for _gid, qubits in self.access.items():
        if len(qubits) == 2:
            a, b = qubits[0], qubits[1]
            if a == b:
                continue
            if a > b:
                a, b = b, a
            edge_w[(a, b)] += 1
            active.add(a); active.add(b)

    adj = defaultdict(list)
    edges = []
    weighted_degree = defaultdict(float)
    for (a, b), w in edge_w.items():
        adj[a].append((b, w))
        adj[b].append((a, w))
        edges.append((a, b, w))
        weighted_degree[a] += w
        weighted_degree[b] += w

    # 2) Hypothesis: seed at centrality-maximal physical qubit,
    #    then expand neighbors outward in the dense connectivity region.
    pi = [None] * N
    used_phys = set()
    placed_logicals = set()

    if active:
        phys_sorted_by_cent = sorted(
            range(N), key=lambda p: -float(cent.get(p, 0.0))
        )
        seed_phys = phys_sorted_by_cent[0]

        # Hub = highest weighted-degree logical (densest interaction node)
        seed_logical = max(
            active,
            key=lambda q: (weighted_degree.get(q, 0.0), float(act.get(q, 0))),
        )

        pi[seed_logical] = seed_phys
        used_phys.add(seed_phys)
        placed_logicals.add(seed_logical)

        # Frontier: logical -> cumulative weight to already-placed
        frontier = {}
        for (nb, w) in adj[seed_logical]:
            if nb not in placed_logicals:
                frontier[nb] = frontier.get(nb, 0.0) + w

        while frontier:
            # Highest interaction pull to placed set wins; degree breaks ties
            L = max(
                frontier,
                key=lambda x: (frontier[x], weighted_degree.get(x, 0.0)),
            )
            del frontier[L]
            if L in placed_logicals:
                continue

            # Place L on the free physical minimizing routing cost to
            # already-placed neighbors; small centrality bonus packs the
            # core tightly around the seed.
            best_p = None
            best_cost = float("inf")
            for p in range(N):
                if p in used_phys:
                    continue
                cost = 0.0
                for (nb, w) in adj[L]:
                    if nb in placed_logicals:
                        cost += w * D[p][pi[nb]]
                cost -= 1e-3 * float(cent.get(p, 0.0))
                if cost < best_cost:
                    best_cost = cost
                    best_p = p
            if best_p is None:
                break
            pi[L] = best_p
            used_phys.add(best_p)
            placed_logicals.add(L)

            for (nb, w) in adj[L]:
                if nb not in placed_logicals:
                    frontier[nb] = frontier.get(nb, 0.0) + w

        # Handle disconnected QIG components: re-seed from next-most-central
        # unused physical and a new hub among remaining active logicals.
        remaining_active = [L for L in active if L not in placed_logicals]
        while remaining_active:
            new_hub = max(
                remaining_active,
                key=lambda q: (weighted_degree.get(q, 0.0), float(act.get(q, 0))),
            )
            new_seed = None
            for p in phys_sorted_by_cent:
                if p not in used_phys:
                    new_seed = p
                    break
            if new_seed is None:
                break
            pi[new_hub] = new_seed
            used_phys.add(new_seed)
            placed_logicals.add(new_hub)

            frontier = {}
            for (nb, w) in adj[new_hub]:
                if nb not in placed_logicals:
                    frontier[nb] = frontier.get(nb, 0.0) + w

            while frontier:
                L = max(
                    frontier,
                    key=lambda x: (frontier[x], weighted_degree.get(x, 0.0)),
                )
                del frontier[L]
                if L in placed_logicals:
                    continue
                best_p = None
                best_cost = float("inf")
                for p in range(N):
                    if p in used_phys:
                        continue
                    cost = 0.0
                    for (nb, w) in adj[L]:
                        if nb in placed_logicals:
                            cost += w * D[p][pi[nb]]
                    cost -= 1e-3 * float(cent.get(p, 0.0))
                    if cost < best_cost:
                        best_cost = cost
                        best_p = p
                if best_p is None:
                    break
                pi[L] = best_p
                used_phys.add(best_p)
                placed_logicals.add(L)
                for (nb, w) in adj[L]:
                    if nb not in placed_logicals:
                        frontier[nb] = frontier.get(nb, 0.0) + w

            remaining_active = [L for L in active if L not in placed_logicals]

        # Isolated active logicals (zero-degree in QIG): drop on most central free phys
        for L in sorted(
            [q for q in active if q not in placed_logicals],
            key=lambda q: -float(act.get(q, 0)),
        ):
            best_p = None
            best_c = -1.0
            for p in range(N):
                if p in used_phys:
                    continue
                c = float(cent.get(p, 0.0))
                if c > best_c:
                    best_c = c
                    best_p = p
            if best_p is None:
                break
            pi[L] = best_p
            used_phys.add(best_p)
            placed_logicals.add(L)

    # 3) Fill remaining (idle) logicals with remaining physicals
    free_phys = [p for p in range(N) if p not in used_phys]
    fi = 0
    for L in range(N):
        if pi[L] is None:
            pi[L] = free_phys[fi]
            fi += 1

    # 4) Simulated-annealing refinement on Σ w·D (better parent)
    def total_energy(perm):
        e = 0.0
        for (a, b, w) in edges:
            e += w * D[perm[a]][perm[b]]
        return e

    cur_E = total_energy(pi)
    best_pi = list(pi)
    best_E = cur_E

    if edges and len(active) >= 2:
        rng = random.Random(0xC0FFEE)
        active_list = list(active)
        iters = max(2000, 50 * N + 20 * len(edges))
        iters = min(iters, 50000)
        T0 = max(1.0, 0.5 * (cur_E / max(1, len(edges))) + 1.0)
        T_end = 1e-3
        cooling = (T_end / T0) ** (1.0 / max(1, iters - 1))
        T = T0

        for _ in range(iters):
            i = active_list[rng.randrange(len(active_list))]
            j = rng.randrange(N)
            if j == i:
                j = (j + 1) % N
            before = 0.0
            for (nb, w) in adj[i]:
                if nb == j:
                    before += w * D[pi[i]][pi[j]]
                else:
                    before += w * D[pi[i]][pi[nb]]
            for (nb, w) in adj[j]:
                if nb == i:
                    continue
                before += w * D[pi[j]][pi[nb]]
            pi[i], pi[j] = pi[j], pi[i]
            after = 0.0
            for (nb, w) in adj[i]:
                if nb == j:
                    after += w * D[pi[i]][pi[j]]
                else:
                    after += w * D[pi[i]][pi[nb]]
            for (nb, w) in adj[j]:
                if nb == i:
                    continue
                after += w * D[pi[j]][pi[nb]]
            dE = after - before
            if dE <= 0 or rng.random() < math.exp(-dE / max(T, 1e-12)):
                cur_E += dE
                if cur_E < best_E:
                    best_E = cur_E
                    best_pi = list(pi)
            else:
                pi[i], pi[j] = pi[j], pi[i]
            T *= cooling

        pi = best_pi

    # 5) Write outputs
    self.mapping_dict = list(pi)
    self.reverse_mapping_dict = [0] * N
    for L in range(N):
        self.reverse_mapping_dict[self.mapping_dict[L]] = L

    assert len(set(self.mapping_dict)) == len(self.mapping_dict)

def init_mapping(self):
    from collections import defaultdict
    import math

    N = int(self.num_qubits)

    # ---- 1. collect active logical qubits and 2q interactions from self.access ----
    interactions = []  # list of (l1, l2, weight)
    active_logicals = set()
    pair_w = defaultdict(int)
    for gate_id, qubits in self.access.items():
        if len(qubits) == 2:
            a, b = int(qubits[0]), int(qubits[1])
            if a == b:
                continue
            active_logicals.add(a); active_logicals.add(b)
            key = (a, b) if a < b else (b, a)
            pair_w[key] += 1

    # prefer the prebuilt QIG when present; else use pair_w
    qig = getattr(self, "qubit_interaction_graph", None)
    if qig is not None:
        edges = []
        seen = set()
        for u, nbrs in qig.items():
            for v, w in nbrs.items():
                if u == v:
                    continue
                key = (u, v) if u < v else (v, u)
                if key in seen:
                    continue
                seen.add(key)
                if w > 0:
                    edges.append((key[0], key[1], int(w)))
                    active_logicals.add(int(key[0]))
                    active_logicals.add(int(key[1]))
        if not edges:
            edges = [(u, v, w) for (u, v), w in pair_w.items()]
    else:
        edges = [(u, v, w) for (u, v), w in pair_w.items()]

    edges.sort(key=lambda e: -e[2])
    # define "heavy" set: top half of edges, plus those with weight >= median*2
    if edges:
        weights_sorted = sorted([e[2] for e in edges])
        median_w = weights_sorted[len(weights_sorted)//2]
        heavy_cutoff = max(1, median_w)
        heavy_edges = [e for e in edges if e[2] >= heavy_cutoff]
        if not heavy_edges:
            heavy_edges = edges[:max(1, len(edges)//2)]
    else:
        heavy_edges = []

    # ---- 2. logical activity for ordering ----
    log_act = getattr(self, "logical_activity", None)
    def activity(L):
        if log_act is not None:
            return log_act.get(L, 0)
        return sum(w for (a, b, w) in edges if a == L or b == L)

    # ---- physical ordering by centrality ----
    pc = getattr(self, "physical_centrality", None)
    if pc:
        phys_ordered = sorted(range(N), key=lambda p: -pc.get(p, 0.0))
    else:
        # fallback: order by sum-of-distances (low = central)
        dm = self.distance_matrix
        phys_ordered = sorted(range(N), key=lambda p: sum(dm[p][q] for q in range(N)))

    # ---- 3. initialize domains ----
    logicals = sorted(active_logicals)
    if not logicals:
        # nothing to do: identity mapping
        self.mapping_dict = list(range(N))
        self.reverse_mapping_dict = list(range(N))
        assert len(set(self.mapping_dict)) == len(self.mapping_dict)
        return

    domains = {L: list(phys_ordered) for L in logicals}

    # diameter for budget scaling
    dm = self.distance_matrix
    try:
        diameter = max(dm[i][j] for i in range(N) for j in range(N))
        if diameter <= 0:
            diameter = N
    except Exception:
        diameter = N

    max_w = max((e[2] for e in edges), default=1)

    def dist_budget(w):
        # heavier edge -> tighter budget; weight 1 => full diameter, top weight => ~2
        frac = w / max_w
        budget = max(2, int(round(diameter * (1.0 - 0.65 * frac))))
        return budget

    # ---- 4. AC-3 arc consistency over heavy edges ----
    constraints = defaultdict(list)  # logical -> list of (neighbor, budget)
    for (u, v, w) in heavy_edges:
        if u in domains and v in domains:
            b = dist_budget(w)
            constraints[u].append((v, b))
            constraints[v].append((u, b))

    def revise(xi, xj, budget):
        removed = False
        keep = []
        Dj = domains[xj]
        if not Dj:
            return False
        Dj_set = set(Dj)
        for pi in domains[xi]:
            # need at least one pj in Dj with pj != pi and dist <= budget
            ok = False
            for pj in Dj_set:
                if pj == pi:
                    continue
                if dm[pi][pj] <= budget:
                    ok = True
                    break
            if ok:
                keep.append(pi)
            else:
                removed = True
        if removed:
            domains[xi] = keep
        return removed

    queue = []
    for u, lst in constraints.items():
        for (v, b) in lst:
            queue.append((u, v, b))

    ac_iters = 0
    ac_cap = 8 * (len(queue) + 1) + 4 * N
    while queue and ac_iters < ac_cap:
        ac_iters += 1
        xi, xj, b = queue.pop(0)
        if revise(xi, xj, b):
            if not domains[xi]:
                # empty domain -> relax: reseed with centrality order, stop AC
                domains[xi] = list(phys_ordered)
                queue = []
                break
            for (xk, bk) in constraints.get(xi, []):
                if xk != xj:
                    queue.append((xk, xi, bk))

    # ---- 5. backtracking DFS with MRV + activity ordering ----
    assignment = {}
    used = set()
    node_cap = [20000]  # mutable counter

    def order_vars():
        unassigned = [L for L in logicals if L not in assignment]
        unassigned.sort(key=lambda L: (len(domains[L]), -activity(L)))
        return unassigned

    def value_order(L):
        # prefer physicals that minimize sum of distances to already-assigned partners
        cands = [p for p in domains[L] if p not in used]
        # build partner list weight pairs
        partners = []
        for (a, b, w) in edges:
            if a == L and b in assignment:
                partners.append((assignment[b], w))
            elif b == L and a in assignment:
                partners.append((assignment[a], w))
        if not partners:
            return cands  # already centrality-ordered
        def cost(p):
            c = 0.0
            for (pp, w) in partners:
                c += w * dm[p][pp]
            # break ties with centrality (lower idx in phys_ordered = better)
            return c
        return sorted(cands, key=cost)

    def consistent(L, p):
        for (a, b, w) in heavy_edges:
            if a == L and b in assignment:
                if dm[p][assignment[b]] > dist_budget(w):
                    return False
            elif b == L and a in assignment:
                if dm[p][assignment[a]] > dist_budget(w):
                    return False
        return True

    def dfs():
        if node_cap[0] <= 0:
            return False
        node_cap[0] -= 1
        remaining = order_vars()
        if not remaining:
            return True
        L = remaining[0]
        for p in value_order(L):
            if p in used:
                continue
            if not consistent(L, p):
                continue
            assignment[L] = p
            used.add(p)
            if dfs():
                return True
            del assignment[L]
            used.discard(p)
        return False

    success = dfs()

    # ---- 6. fallback warm start if CSP failed ----
    if not success or len(assignment) < len(logicals):
        try:
            from src.mapping.initial_mapping import generate_structure_aware_initial_mapping
            warm_map, warm_rev = generate_structure_aware_initial_mapping(
                self.access, self.backend, self.distance_matrix, self.num_qubits
            )
            assignment = {}
            used = set()
            for L in logicals:
                p = warm_map[L] if L < len(warm_map) else None
                if p is not None and p not in used and 0 <= p < N:
                    assignment[L] = p
                    used.add(p)
        except Exception:
            pass

    # ---- final sweep: ensure full-length lists and injection ----
    mapping = [-1] * N
    reverse = [-1] * N
    used_phys = set()
    for L, p in assignment.items():
        if 0 <= L < N and 0 <= p < N and p not in used_phys:
            mapping[L] = p
            reverse[p] = L
            used_phys.add(p)

    free_phys = [p for p in phys_ordered if p not in used_phys]
    fp_idx = 0
    for L in range(N):
        if mapping[L] == -1:
            while fp_idx < len(free_phys) and free_phys[fp_idx] in used_phys:
                fp_idx += 1
            if fp_idx < len(free_phys):
                p = free_phys[fp_idx]; fp_idx += 1
                mapping[L] = p
                reverse[p] = L
                used_phys.add(p)
            else:
                # last-resort identity (shouldn't trigger given sets above)
                for p in range(N):
                    if p not in used_phys:
                        mapping[L] = p
                        reverse[p] = L
                        used_phys.add(p)
                        break

    self.mapping_dict = mapping
    self.reverse_mapping_dict = reverse
    assert len(set(self.mapping_dict)) == len(self.mapping_dict)

def init_mapping(self):
    import numpy as np

    N = int(self.num_qubits)

    if N == 0:
        self.mapping_dict = []
        self.reverse_mapping_dict = []
        assert len(set(self.mapping_dict)) == len(self.mapping_dict)
        return

    def _greedy_assign(cost):
        n = cost.shape[0]
        used = [False] * n
        col = [0] * n
        order = list(np.argsort(cost.min(axis=1)))
        for r in order:
            best_c, best_v = -1, float("inf")
            for c in range(n):
                if used[c]:
                    continue
                v = float(cost[r, c])
                if v < best_v:
                    best_v, best_c = v, c
            if best_c < 0:
                for c in range(n):
                    if not used[c]:
                        best_c = c
                        break
            col[r] = best_c
            used[best_c] = True
        return list(range(n)), col

    try:
        from scipy.optimize import linear_sum_assignment

        def _assign(M):
            r, c = linear_sum_assignment(M)
            return list(r), list(c)
    except Exception:
        def _assign(M):
            return _greedy_assign(M)

    W = np.zeros((N, N), dtype=float)
    for _gid, qubits in self.access.items():
        if len(qubits) == 2:
            q1, q2 = int(qubits[0]), int(qubits[1])
            if 0 <= q1 < N and 0 <= q2 < N and q1 != q2:
                W[q1, q2] += 1.0
                W[q2, q1] += 1.0

    D = np.zeros((N, N), dtype=float)
    for i in range(N):
        for j in range(N):
            try:
                D[i, j] = float(self.distance_matrix[i][j])
            except Exception:
                D[i, j] = 0.0

    if W.sum() == 0.0:
        self.mapping_dict = list(range(N))
        self.reverse_mapping_dict = list(range(N))
        assert len(set(self.mapping_dict)) == len(self.mapping_dict)
        return

    X = np.full((N, N), 1.0 / N, dtype=float)

    max_iter = max(10, min(50, 3 * N))
    for it in range(max_iter):
        G = W @ X @ D
        if not np.all(np.isfinite(G)):
            break
        r_idx, c_idx = _assign(G)
        S = np.zeros((N, N), dtype=float)
        for ri, ci in zip(r_idx, c_idx):
            S[ri, ci] = 1.0
        gamma = 2.0 / (it + 2.0)
        X = (1.0 - gamma) * X + gamma * S

    Xs = np.maximum(X, 1e-12)
    for _ in range(50):
        rs = Xs.sum(axis=1, keepdims=True)
        rs[rs == 0] = 1.0
        Xs = Xs / rs
        cs = Xs.sum(axis=0, keepdims=True)
        cs[cs == 0] = 1.0
        Xs = Xs / cs

    if not np.all(np.isfinite(Xs)):
        Xs = np.full((N, N), 1.0 / N, dtype=float)

    r_idx, c_idx = _assign(-Xs)

    mapping = [-1] * N
    reverse = [-1] * N
    used_phys = [False] * N
    for ri, ci in zip(r_idx, c_idx):
        ri, ci = int(ri), int(ci)
        if 0 <= ri < N and 0 <= ci < N and not used_phys[ci] and mapping[ri] == -1:
            mapping[ri] = ci
            reverse[ci] = ri
            used_phys[ci] = True

    free_phys = [p for p in range(N) if not used_phys[p]]
    fp_iter = iter(free_phys)
    for l in range(N):
        if mapping[l] == -1:
            try:
                p = next(fp_iter)
            except StopIteration:
                p = l
            mapping[l] = p
            reverse[p] = l

    self.mapping_dict = mapping
    self.reverse_mapping_dict = reverse

    assert len(set(self.mapping_dict)) == len(self.mapping_dict)

def init_mapping(self):
    import networkx as nx
    from collections import defaultdict

    N = self.num_qubits
    self.mapping_dict = [-1] * N
    self.reverse_mapping_dict = [-1] * N

    logical_edges = defaultdict(int)
    logical_qubits = set()
    access = getattr(self, "access", {}) or {}
    for _gid, qubits in access.items():
        if len(qubits) == 2:
            q1, q2 = qubits[0], qubits[1]
            if q1 == q2 or q1 >= N or q2 >= N:
                continue
            a, b = (q1, q2) if q1 < q2 else (q2, q1)
            logical_edges[(a, b)] += 1
            logical_qubits.add(q1)
            logical_qubits.add(q2)

    adj = defaultdict(set)
    for (a, b) in logical_edges:
        adj[a].add(b)
        adj[b].add(a)

    def ew(a, b):
        if a > b:
            a, b = b, a
        return logical_edges.get((a, b), 0)

    G_phys = nx.Graph()
    G_phys.add_nodes_from(range(N))
    for p in range(N):
        for nbr in self.backend.get(p, set()):
            if p < nbr:
                G_phys.add_edge(p, nbr)

    assigned_logical = set()
    used_physical = set()

    def commit(log_q, phys_q):
        if log_q < 0 or phys_q < 0 or log_q >= N or phys_q >= N:
            return False
        if log_q in assigned_logical or phys_q in used_physical:
            return False
        self.mapping_dict[log_q] = phys_q
        self.reverse_mapping_dict[phys_q] = log_q
        assigned_logical.add(log_q)
        used_physical.add(phys_q)
        return True

    triangles = []
    seen_tri = set()
    for a in logical_qubits:
        for b in adj[a]:
            if b <= a:
                continue
            for c in adj[a] & adj[b]:
                if c <= b:
                    continue
                key = (a, b, c)
                if key in seen_tri:
                    continue
                seen_tri.add(key)
                w = ew(a, b) + ew(a, c) + ew(b, c)
                triangles.append((w, key))
    triangles.sort(reverse=True)

    k4s = []
    seen_k4 = set()
    for _w, (a, b, c) in triangles[:60]:
        common = adj[a] & adj[b] & adj[c]
        for d in common:
            if d <= c:
                continue
            quad = (a, b, c, d)
            if quad in seen_k4:
                continue
            seen_k4.add(quad)
            tw = (ew(a, b) + ew(a, c) + ew(a, d)
                  + ew(b, c) + ew(b, d) + ew(c, d))
            k4s.append((tw, quad))
    k4s.sort(reverse=True)

    stars = []
    for hub in logical_qubits:
        nbrs = list(adj[hub])
        if len(nbrs) >= 3:
            nbrs.sort(key=lambda x: -ew(hub, x))
            top = nbrs[: min(len(nbrs), 4)]
            sw = sum(ew(hub, n) for n in top)
            stars.append((sw, hub, tuple(top)))
    stars.sort(reverse=True)

    def try_anchor(motif_nx, motif_nodes):
        if any(n in assigned_logical for n in motif_nodes):
            return False
        avail = [p for p in range(N) if p not in used_physical]
        if len(avail) < len(motif_nodes):
            return False
        H = G_phys.subgraph(avail).copy()
        try:
            GM = nx.isomorphism.GraphMatcher(H, motif_nx)
            it = GM.subgraph_isomorphisms_iter()
            best = None
            best_score = float("inf")
            tries = 0
            cent = getattr(self, "physical_centrality", {}) or {}
            for iso in it:
                tries += 1
                score = -sum(cent.get(p, 0.0) for p in iso.keys())
                if score < best_score:
                    best_score = score
                    best = iso
                if tries >= 8:
                    break
            if best is None:
                return False
            tentative = {log: phys for phys, log in best.items()}
            if set(tentative.keys()) != set(motif_nodes):
                return False
            if len(set(tentative.values())) != len(tentative):
                return False
            for log, phys in tentative.items():
                if not commit(log, phys):
                    return False
            return True
        except Exception:
            return False

    for _w, (a, b, c) in triangles[:5]:
        m = nx.Graph()
        m.add_edges_from([(a, b), (a, c), (b, c)])
        try_anchor(m, [a, b, c])

    for _w, (a, b, c, d) in k4s[:3]:
        m = nx.Graph()
        m.add_edges_from([(a, b), (a, c), (a, d),
                          (b, c), (b, d), (c, d)])
        try_anchor(m, [a, b, c, d])

    for _sw, hub, leaves in stars[:5]:
        m = nx.Graph()
        for lf in leaves:
            m.add_edge(hub, lf)
        try_anchor(m, [hub] + list(leaves))

    activity = defaultdict(int)
    for (a, b), w in logical_edges.items():
        activity[a] += w
        activity[b] += w
    remaining = sorted(
        [q for q in logical_qubits if q not in assigned_logical],
        key=lambda q: -activity[q],
    )
    cent_map = getattr(self, "physical_centrality", {}) or {}

    for log_q in remaining:
        mapped_nbrs = [n for n in adj[log_q] if n in assigned_logical]
        best_phys = -1
        best_score = float("inf")
        for phys in range(N):
            if phys in used_physical:
                continue
            if mapped_nbrs:
                s = 0.0
                for nb in mapped_nbrs:
                    s += ew(log_q, nb) * self.distance_matrix[phys][self.mapping_dict[nb]]
            else:
                s = -cent_map.get(phys, 0.0) * 1e6
            if s < best_score:
                best_score = s
                best_phys = phys
        if best_phys >= 0:
            commit(log_q, best_phys)

    free_logs = [q for q in range(N) if self.mapping_dict[q] == -1]
    free_phys = [p for p in range(N) if p not in used_physical]
    for log_q, phys_q in zip(free_logs, free_phys):
        commit(log_q, phys_q)

    assert len(set(self.mapping_dict)) == len(self.mapping_dict)

def init_mapping(self):
    import numpy as np
    import time

    N = int(self.num_qubits)
    if N <= 0:
        self.mapping_dict = []
        self.reverse_mapping_dict = []
        assert len(set(self.mapping_dict)) == len(self.mapping_dict)
        return

    interactions = {}
    logical_set = set()
    for _gid, qubits in self.access.items():
        for q in qubits:
            logical_set.add(int(q))
        if len(qubits) == 2:
            a, b = int(qubits[0]), int(qubits[1])
            if a == b or a >= N or b >= N:
                continue
            key = (a, b) if a < b else (b, a)
            interactions[key] = interactions.get(key, 0) + 1

    if not interactions:
        self.mapping_dict = list(range(N))
        self.reverse_mapping_dict = list(range(N))
        assert len(set(self.mapping_dict)) == len(self.mapping_dict)
        return

    dist = np.asarray(self.distance_matrix, dtype=np.int32)

    def cost(perm):
        c = 0.0
        for (a, b), w in interactions.items():
            c += w * dist[perm[a]][perm[b]]
        return c

    nbrs = {q: {} for q in logical_set}
    for (a, b), w in interactions.items():
        nbrs[a][b] = w
        nbrs[b][a] = w
    activity = {q: sum(nbrs[q].values()) for q in logical_set}

    max_w = max(interactions.values())
    diameter = int(dist.max()) if dist.size > 0 else 1

    # Heavy-edge tier: must dominate the QIG mass AND survive a minimum gate floor.
    cut = max(2, int(np.ceil(0.4 * max_w)))

    def is_heavy(w):
        return w >= cut

    def radius(w):
        if max_w <= 1:
            return diameter
        ratio = w / float(max_w)
        r = int(round(diameter * (1.0 - 0.7 * ratio)))
        return max(1, min(diameter, r))

    def heavy_deg(q):
        return sum(1 for nb, w in nbrs[q].items() if is_heavy(w))

    # Most-constrained-variable ordering: heavy-edge degree, then total activity.
    var_order = sorted(
        logical_set,
        key=lambda q: (-heavy_deg(q), -activity[q]),
    )

    centrality = getattr(self, "physical_centrality", {}) or {}
    cent_arr = np.array([float(centrality.get(p, 0.0)) for p in range(N)], dtype=float)
    initial_domain = sorted(range(N), key=lambda p: -cent_arr[p])

    best = {"perm": None, "cost": float("inf")}
    deadline = time.time() + 1.2
    branch_cap = 8 if N <= 32 else 5

    def fwd_check(q, p, idx, doms):
        # Arc-consistency: prune every unassigned logical's domain w.r.t. the new
        # assignment q -> p. Heavy QIG edges enforce a tight distance ceiling.
        new_doms = {}
        for q2 in var_order[idx + 1:]:
            w_edge = nbrs[q].get(q2, 0)
            rad = radius(w_edge) if is_heavy(w_edge) else None
            filtered = []
            for p2 in doms[q2]:
                if p2 == p:
                    continue
                if rad is not None and dist[p][p2] > rad:
                    continue
                filtered.append(p2)
            if not filtered:
                return None
            new_doms[q2] = filtered
        return new_doms

    def value_key(q, p, assign):
        s = 0.0
        for nb, w in nbrs[q].items():
            if nb in assign:
                s += w * dist[p][assign[nb]]
        return (s, -cent_arr[p])

    def bt(idx, doms, assign):
        if time.time() > deadline:
            return
        if idx == len(var_order):
            used = set(assign.values())
            unused = [p for p in range(N) if p not in used]
            perm = [0] * N
            ui = 0
            for q in range(N):
                if q in assign:
                    perm[q] = assign[q]
                else:
                    perm[q] = unused[ui]
                    ui += 1
            c = cost(perm)
            if c < best["cost"]:
                best["cost"] = c
                best["perm"] = perm
            return
        q = var_order[idx]
        # Re-verify domain against all currently-assigned heavy neighbors.
        valid = []
        for p in doms[q]:
            ok = True
            for nb, w in nbrs[q].items():
                if nb in assign and is_heavy(w):
                    if dist[p][assign[nb]] > radius(w):
                        ok = False
                        break
            if ok:
                valid.append(p)
        if not valid:
            return
        valid.sort(key=lambda p: value_key(q, p, assign))
        for p in valid[:branch_cap]:
            assign[q] = p
            new_doms = fwd_check(q, p, idx, doms)
            if new_doms is not None:
                bt(idx + 1, new_doms, assign)
            del assign[q]
            if time.time() > deadline:
                return

    domains_init = {q: list(initial_domain) for q in logical_set}
    bt(0, domains_init, {})

    if best["perm"] is None:
        # Locality too tight for this topology: greedy weighted placement.
        order = sorted(logical_set, key=lambda q: -activity[q])
        cent_sorted = sorted(range(N), key=lambda p: -cent_arr[p])
        used = [False] * N
        placed = {}
        for q in order:
            best_p, best_s = None, float("inf")
            for p in cent_sorted:
                if used[p]:
                    continue
                s = 0.0
                for nb, w in nbrs[q].items():
                    if nb in placed:
                        s += w * dist[p][placed[nb]]
                if s < best_s:
                    best_s = s
                    best_p = p
            placed[q] = best_p
            used[best_p] = True
        perm = [0] * N
        unused = [p for p in range(N) if not used[p]]
        ui = 0
        for q in range(N):
            if q in placed:
                perm[q] = placed[q]
            else:
                perm[q] = unused[ui]
                ui += 1
        best["perm"] = perm
        best["cost"] = cost(perm)

    perm = list(best["perm"])
    best_cost = cost(perm)

    # Pairwise-swap polish restricted to interacting logicals.
    interacting = sorted(logical_set, key=lambda q: -activity[q])
    improved = True
    passes = 0
    while improved and passes < 4:
        improved = False
        passes += 1
        for i_idx, i in enumerate(interacting):
            for j in interacting[i_idx + 1:]:
                perm[i], perm[j] = perm[j], perm[i]
                c = cost(perm)
                if c < best_cost - 1e-9:
                    best_cost = c
                    improved = True
                else:
                    perm[i], perm[j] = perm[j], perm[i]

    self.mapping_dict = [int(x) for x in perm]
    self.reverse_mapping_dict = [0] * N
    for l, p in enumerate(self.mapping_dict):
        self.reverse_mapping_dict[p] = l

    assert len(set(self.mapping_dict)) == len(self.mapping_dict)

def init_mapping(self):
    import numpy as np
    import random

    N = int(self.num_qubits)

    logical_set = set()
    for _gid, qubits in self.access.items():
        for q in qubits:
            qi = int(q)
            if 0 <= qi < N:
                logical_set.add(qi)

    if N <= 0:
        self.mapping_dict = []
        self.reverse_mapping_dict = []
        assert len(set(self.mapping_dict)) == len(self.mapping_dict)
        return

    if not logical_set:
        self.mapping_dict = list(range(N))
        self.reverse_mapping_dict = list(range(N))
        assert len(set(self.mapping_dict)) == len(self.mapping_dict)
        return

    # Collect 2-qubit interactions (for GA fitness)
    interactions = {}
    for _gid, qubits in self.access.items():
        if len(qubits) == 2:
            a, b = int(qubits[0]), int(qubits[1])
            if a == b or not (0 <= a < N and 0 <= b < N):
                continue
            key = (a, b) if a < b else (b, a)
            interactions[key] = interactions.get(key, 0) + 1

    # ---------- Feature vectors over logical-qubit space ----------
    # Combine QIG (count) and temporal_interaction_graph (early-gate weighted)
    qig = self.qubit_interaction_graph
    tig = getattr(self, "temporal_interaction_graph", None)

    features = np.zeros((N, N), dtype=float)
    for q in logical_set:
        if q in qig:
            for nb, w in qig[q].items():
                nb_i = int(nb)
                if 0 <= nb_i < N:
                    features[q, nb_i] = float(w)
        if tig is not None and q in tig:
            for nb, w in tig[q].items():
                nb_i = int(nb)
                if 0 <= nb_i < N:
                    features[q, nb_i] += 0.5 * float(w)
        features[q, q] = max(features[q, q],
                             0.1 * float(self.logical_activity.get(q, 0)))
        nrm = float(np.linalg.norm(features[q]))
        if nrm > 0.0:
            features[q] = features[q] / nrm

    # ---------- Hardware distance & centrality ----------
    try:
        D = np.asarray(self.distance_matrix, dtype=float)
        if D.shape != (N, N):
            D = np.zeros((N, N), dtype=float)
    except Exception:
        D = np.zeros((N, N), dtype=float)

    centrality = getattr(self, "physical_centrality", {}) or {}
    cent_arr = np.array([float(centrality.get(p, 0.0)) for p in range(N)], dtype=float)

    rng = np.random.default_rng(0xC0DE)
    logical_list = sorted(logical_set)

    # ---------- Kohonen SOM over the hardware coupling graph ----------
    # Initialise each physical qubit's weight from the mean feature vector,
    # scaled by its hardware centrality, plus small noise. Central physicals
    # therefore start "wider open" to hub-like logical qubits.
    if logical_list:
        mean_feature = features[logical_list].mean(axis=0)
    else:
        mean_feature = np.zeros(N, dtype=float)
    W = np.tile(mean_feature, (N, 1)).astype(float)
    if cent_arr.max() > 0.0:
        scale = cent_arr / (cent_arr.max() + 1e-12)
    else:
        scale = np.ones(N, dtype=float)
    W = W * scale[:, None]
    W = W + rng.uniform(0.0, 1e-3, size=(N, N))

    raw_act = np.array(
        [max(float(self.logical_activity.get(q, 0)), 1.0) for q in logical_list],
        dtype=float,
    )
    probs = raw_act / raw_act.sum()

    max_d = float(D.max()) if D.size > 0 else 1.0
    initial_radius = max(1.5, max_d / 2.0)
    final_radius = 0.5
    initial_lr = 0.7
    final_lr = 0.02
    num_iter = max(150, 12 * len(logical_list))

    for t in range(num_iter):
        frac = t / max(1, num_iter - 1)
        lr = initial_lr * (final_lr / initial_lr) ** frac
        radius = initial_radius * (final_radius / initial_radius) ** frac

        idx = int(rng.choice(len(logical_list), p=probs))
        q = logical_list[idx]
        x = features[q]

        diffs = W - x[None, :]
        sqd = np.einsum("ij,ij->i", diffs, diffs)
        # tiny centrality bias breaks ties toward central physicals
        bmu = int(np.argmin(sqd - 1e-6 * cent_arr))

        d_to_bmu = D[bmu]
        h = np.exp(-(d_to_bmu * d_to_bmu) / (2.0 * radius * radius + 1e-12))
        h = np.where(d_to_bmu <= radius + 1e-9, h, 0.0)
        W += (lr * h)[:, None] * (x[None, :] - W)

    # ---------- Greedy BMU assignment (highest-activity logical first) ----------
    som_map = [-1] * N
    som_rev = [-1] * N
    used = [False] * N

    order_logicals = sorted(
        logical_list,
        key=lambda q: -float(self.logical_activity.get(q, 0)),
    )
    for q in order_logicals:
        x = features[q]
        diffs = W - x[None, :]
        sqd = np.einsum("ij,ij->i", diffs, diffs)
        keys = sqd - 1e-6 * cent_arr
        order = np.argsort(keys, kind="stable")
        for p in order:
            p_i = int(p)
            if not used[p_i]:
                som_map[q] = p_i
                som_rev[p_i] = q
                used[p_i] = True
                break

    unused = sorted([p for p in range(N) if not used[p]],
                    key=lambda p: -cent_arr[p])
    idle = [q for q in range(N) if som_map[q] == -1]
    ui = 0
    for q in idle:
        if ui < len(unused):
            p_i = unused[ui]
            ui += 1
            som_map[q] = p_i
            som_rev[p_i] = q

    som_perm = list(som_map)

    # ---------- GA refinement seeded by SOM result + structure-aware embedding ----------
    def fitness(perm):
        s = 0.0
        for (a, b), w in interactions.items():
            s += w * D[perm[a], perm[b]]
        return s

    def random_perm():
        p = list(range(N))
        random.shuffle(p)
        return p

    def tournament(pop, fits, k=3):
        if len(pop) <= 1:
            return list(pop[0]) if pop else random_perm()
        kk = min(k, len(pop))
        idxs = random.sample(range(len(pop)), kk)
        best_i = min(idxs, key=lambda i: fits[i])
        return list(pop[best_i])

    def pmx(p1, p2):
        size = len(p1)
        if size < 2:
            return list(p1)
        child = [-1] * size
        a, b = sorted(random.sample(range(size), 2))
        for i in range(a, b + 1):
            child[i] = p1[i]
        seg_set = set(child[a:b + 1])
        pos_p2 = {v: i for i, v in enumerate(p2)}
        for i in range(a, b + 1):
            val = p2[i]
            if val in seg_set:
                continue
            j = i
            guard = 0
            while a <= j <= b and guard < size + 1:
                j = pos_p2[p1[j]]
                guard += 1
            if 0 <= j < size and child[j] == -1:
                child[j] = val
        for i in range(size):
            if child[i] == -1:
                child[i] = p2[i]
        if len(set(child)) != size:
            return list(p1)
        return child

    def cycle_crossover(p1, p2):
        size = len(p1)
        if size < 2:
            return list(p1)
        child = [-1] * size
        idx_p2 = {v: i for i, v in enumerate(p2)}
        i = 0
        guard = 0
        while child[i] == -1 and guard < size + 1:
            child[i] = p1[i]
            nxt = idx_p2.get(p1[i], i)
            if nxt == i:
                break
            i = nxt
            guard += 1
        for j in range(size):
            if child[j] == -1:
                child[j] = p2[j]
        if len(set(child)) != size:
            return list(p1)
        return child

    def mutate(perm, rate=0.25):
        if len(perm) >= 2 and random.random() < rate:
            i, j = random.sample(range(len(perm)), 2)
            perm[i], perm[j] = perm[j], perm[i]
        return perm

    random.seed(0xBEEF)

    pop_size = 30 if N >= 4 else max(4, N)
    generations = 30 if N >= 4 else 10

    population = []
    if len(som_perm) == N and len(set(som_perm)) == N and all(0 <= v < N for v in som_perm):
        population.append(list(som_perm))

    try:
        from src.mapping.initial_mapping import generate_structure_aware_initial_mapping
        seed_map, _ = generate_structure_aware_initial_mapping(
            self.access, self.backend, self.distance_matrix, self.num_qubits
        )
        seed_list = list(seed_map)
        if (len(seed_list) == N and len(set(seed_list)) == N
                and all(0 <= v < N for v in seed_list)):
            population.append(seed_list)
    except Exception:
        pass

    population.append(list(range(N)))
    while len(population) < pop_size:
        population.append(random_perm())

    fits = [fitness(p) for p in population]
    best_i = min(range(len(population)), key=lambda i: fits[i])
    best = list(population[best_i])
    best_fit = fits[best_i]

    for _gen in range(generations):
        new_pop = [list(best)]
        while len(new_pop) < pop_size:
            p1 = tournament(population, fits)
            p2 = tournament(population, fits)
            if random.random() < 0.5:
                child = pmx(p1, p2)
            else:
                child = cycle_crossover(p1, p2)
            child = mutate(child, rate=0.25)
            if len(child) == N and len(set(child)) == N:
                new_pop.append(child)
            else:
                new_pop.append(random_perm())
        population = new_pop
        fits = [fitness(p) for p in population]
        cur_i = min(range(len(population)), key=lambda i: fits[i])
        if fits[cur_i] < best_fit:
            best_fit = fits[cur_i]
            best = list(population[cur_i])

    if (len(best) != N or len(set(best)) != N
            or any(not (0 <= v < N) for v in best)):
        best = list(range(N))

    self.mapping_dict = list(best)
    self.reverse_mapping_dict = [0] * N
    for logical_q, physical_q in enumerate(self.mapping_dict):
        self.reverse_mapping_dict[physical_q] = logical_q

    assert len(set(self.mapping_dict)) == len(self.mapping_dict)

def init_mapping(self):
    from collections import defaultdict, deque

    N = self.num_qubits
    self.mapping_dict = [-1] * N
    self.reverse_mapping_dict = [-1] * N

    if N == 0:
        assert len(set(self.mapping_dict)) == len(self.mapping_dict)
        return

    logical_edges = defaultdict(int)
    logical_qubits = set()
    access = getattr(self, "access", {}) or {}
    for _gid, qubits in access.items():
        if len(qubits) == 2:
            q1, q2 = qubits[0], qubits[1]
            if q1 == q2 or q1 < 0 or q2 < 0 or q1 >= N or q2 >= N:
                continue
            a, b = (q1, q2) if q1 < q2 else (q2, q1)
            logical_edges[(a, b)] += 1
            logical_qubits.add(q1)
            logical_qubits.add(q2)

    adj = defaultdict(set)
    for (a, b) in logical_edges:
        adj[a].add(b)
        adj[b].add(a)

    def ew(a, b):
        if a > b:
            a, b = b, a
        return logical_edges.get((a, b), 0)

    assigned_logical = set()
    used_physical = set()

    def commit(log_q, phys_q):
        if log_q < 0 or phys_q < 0 or log_q >= N or phys_q >= N:
            return False
        if log_q in assigned_logical or phys_q in used_physical:
            return False
        self.mapping_dict[log_q] = phys_q
        self.reverse_mapping_dict[phys_q] = log_q
        assigned_logical.add(log_q)
        used_physical.add(phys_q)
        return True

    # ---- HYPOTHESIS: weighted Hamiltonian-like path in QIG ----
    def build_logical_heavy_path():
        if not logical_edges:
            return []
        start = max(logical_edges.items(), key=lambda kv: kv[1])[0]
        path = [start[0], start[1]]
        in_path = set(path)
        # Greedy two-sided extension by heaviest unused neighbor
        extending = True
        while extending:
            extending = False
            best_choice = None  # (weight, end_side, neighbor)
            for side in (0, -1):
                end = path[side]
                for nb in adj[end]:
                    if nb in in_path:
                        continue
                    w = ew(end, nb)
                    if best_choice is None or w > best_choice[0]:
                        best_choice = (w, side, nb)
            if best_choice is not None and best_choice[0] > 0:
                _, side, nb = best_choice
                if side == 0:
                    path.insert(0, nb)
                else:
                    path.append(nb)
                in_path.add(nb)
                extending = True
        # Attach any remaining active logicals (disconnected components) by activity
        remaining_log = sorted(
            [q for q in logical_qubits if q not in in_path],
            key=lambda q: -sum(ew(q, n) for n in adj[q]),
        )
        for q in remaining_log:
            w_front = ew(q, path[0])
            w_back = ew(q, path[-1])
            if w_front >= w_back:
                path.insert(0, q)
            else:
                path.append(q)
            in_path.add(q)
        return path

    logical_path = build_logical_heavy_path()

    # ---- Long path in hardware graph via double BFS + centrality extension ----
    def bfs_longest_from(src):
        prev = {src: None}
        order = [src]
        q = deque([src])
        farthest = src
        while q:
            node = q.popleft()
            farthest = node
            for nb in self.backend.get(node, set()):
                if nb not in prev:
                    prev[nb] = node
                    order.append(nb)
                    q.append(nb)
        # reconstruct path from src to farthest
        path = []
        cur = farthest
        while cur is not None:
            path.append(cur)
            cur = prev[cur]
        path.reverse()
        return farthest, path

    cent = getattr(self, "physical_centrality", {}) or {}
    if cent:
        seed = max(range(N), key=lambda p: cent.get(p, 0.0))
    else:
        seed = 0
    u, _ = bfs_longest_from(seed)
    v, hw_path = bfs_longest_from(u)
    in_hw = set(hw_path)

    # extend both ends with any free hardware neighbors (greedy by centrality)
    progressing = True
    while progressing:
        progressing = False
        for side in (0, -1):
            end = hw_path[side]
            cands = [p for p in self.backend.get(end, set()) if p not in in_hw]
            if cands:
                cands.sort(key=lambda x: -cent.get(x, 0.0))
                nxt = cands[0]
                if side == 0:
                    hw_path.insert(0, nxt)
                else:
                    hw_path.append(nxt)
                in_hw.add(nxt)
                progressing = True

    # ---- Edge-by-edge alignment of logical path onto hardware path ----
    align_len = min(len(logical_path), len(hw_path))
    for i in range(align_len):
        commit(logical_path[i], hw_path[i])

    # ---- Fallback placement for active logicals not on the path ----
    activity = defaultdict(int)
    for (a, b), w in logical_edges.items():
        activity[a] += w
        activity[b] += w

    remaining = sorted(
        [q for q in logical_qubits if q not in assigned_logical],
        key=lambda q: -activity[q],
    )

    for log_q in remaining:
        mapped_nbrs = [n for n in adj[log_q] if n in assigned_logical]
        best_phys = -1
        best_score = float("inf")
        for phys in range(N):
            if phys in used_physical:
                continue
            if mapped_nbrs:
                s = 0.0
                for nb in mapped_nbrs:
                    s += ew(log_q, nb) * float(
                        self.distance_matrix[phys][self.mapping_dict[nb]]
                    )
            else:
                s = -cent.get(phys, 0.0) * 1e6
            if s < best_score:
                best_score = s
                best_phys = phys
        if best_phys >= 0:
            commit(log_q, best_phys)

    # ---- Fill idle logicals with leftover physicals (centrality-aware) ----
    free_phys = sorted(
        [p for p in range(N) if p not in used_physical],
        key=lambda p: -cent.get(p, 0.0),
    )
    free_logs = [q for q in range(N) if self.mapping_dict[q] == -1]
    for log_q, phys_q in zip(free_logs, free_phys):
        commit(log_q, phys_q)

    assert len(set(self.mapping_dict)) == len(self.mapping_dict)
